@lru_cache(maxsize=1)
def carregar_png_bytes():
    data = base64.b85decode(''.join(_PNG_ASCII85).encode('ascii'))
    if hashlib.sha256(data).hexdigest() != ART_SHA256:
        raise ValueError('Integridade do fundo BG01 comprometida')
    if data[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError('Fundo BG01 não é PNG')
    return data


def carregar_pixmap():
    from PySide6.QtGui import QPixmap
    pm = QPixmap()
    if not pm.loadFromData(carregar_png_bytes(), 'PNG'):
        raise ValueError('Não foi possível carregar o PNG BG01')
    if pm.width() != ART_WIDTH or pm.height() != ART_HEIGHT:
        raise ValueError('Dimensão da arte BG01 inesperada')
    return pm
